const rights = [
{article:'Pasal 27 Ayat (2)',title:'Hak atas pekerjaan dan penghidupan layak',text:'Tiap-tiap warga negara berhak atas pekerjaan dan penghidupan yang layak bagi kemanusiaan.',example:'Kesempatan kerja dan perlakuan dalam pekerjaan perlu menghormati martabat manusia.',duty:'Pemerintah mengembangkan kebijakan ketenagakerjaan; pemberi kerja mematuhi ketentuan ketenagakerjaan.'},
{article:'Pasal 27 Ayat (3)',title:'Hak dan kewajiban membela negara',text:'Setiap warga negara berhak dan wajib ikut serta dalam upaya pembelaan negara.',example:'Partisipasi dapat dilakukan melalui cara yang sah sesuai peraturan perundang-undangan.',duty:'Warga ikut menjaga negara secara bertanggung jawab dan menghormati hukum.'},
{article:'Pasal 28C Ayat (1)',title:'Hak mengembangkan diri',text:'Setiap orang berhak mengembangkan diri melalui pemenuhan kebutuhan dasarnya, berhak mendapat pendidikan dan memperoleh manfaat dari ilmu pengetahuan dan teknologi, seni dan budaya, demi meningkatkan kualitas hidupnya dan demi kesejahteraan umat manusia.',example:'Peserta didik mendapat kesempatan belajar dan mengakses pengetahuan serta teknologi.',duty:'Negara menyelenggarakan pendidikan dan mendukung kesempatan pengembangan diri.'},
{article:'Pasal 28C Ayat (2)',title:'Hak memperjuangkan kepentingan secara kolektif',text:'Setiap orang berhak untuk memajukan dirinya dalam memperjuangkan haknya secara kolektif untuk membangun masyarakat, bangsa, dan negaranya.',example:'Warga bergabung dalam organisasi atau menyampaikan aspirasi bersama secara sah.',duty:'Perjuangan kolektif dilakukan dengan menghormati hak orang lain dan aturan hukum.'},
{article:'Pasal 28D Ayat (1)',title:'Jaminan dan kepastian hukum yang adil',text:'Setiap orang berhak atas pengakuan, jaminan, perlindungan, dan kepastian hukum yang adil serta perlakuan yang sama di hadapan hukum.',example:'Laporan diperiksa secara objektif dan setiap pihak diperlakukan sesuai prosedur hukum.',duty:'Aparat menjalankan kewenangan berdasarkan hukum; masyarakat menghormati proses yang adil.'},
{article:'Pasal 28D Ayat (2)',title:'Hak dalam hubungan kerja',text:'Setiap orang berhak untuk bekerja serta mendapat imbalan dan perlakuan yang adil dan layak dalam hubungan kerja.',example:'Pekerja menerima upah dan perlakuan sesuai perjanjian serta peraturan ketenagakerjaan.',duty:'Pemberi kerja dan pekerja memenuhi kewajiban sesuai ketentuan yang berlaku.'},
{article:'Pasal 28D Ayat (3)',title:'Kesempatan yang sama dalam pemerintahan',text:'Setiap warga negara berhak memperoleh kesempatan yang sama dalam pemerintahan.',example:'Kesempatan mengikuti proses seleksi jabatan publik diberikan berdasarkan ketentuan yang adil.',duty:'Seleksi dan partisipasi dalam pemerintahan dijalankan secara transparan dan sesuai hukum.'},
{article:'Pasal 28D Ayat (4)',title:'Hak atas status kewarganegaraan',text:'Setiap orang berhak atas status kewarganegaraan.',example:'Seseorang berhak memperoleh kepastian mengenai status kewarganegaraan dan dokumen terkait.',duty:'Administrasi kewarganegaraan dijalankan sesuai hukum dan menjamin kepastian status.'},
{article:'Pasal 28E Ayat (1)',title:'Kebebasan beragama, memilih pendidikan, pekerjaan, dan tempat tinggal',text:'Setiap orang bebas memeluk agama dan beribadat menurut agamanya, memilih pendidikan dan pengajaran, memilih pekerjaan, memilih kewarganegaraan, memilih tempat tinggal di wilayah negara dan meninggalkannya, serta berhak kembali.',example:'Individu menentukan pendidikan, pekerjaan, dan keyakinannya tanpa paksaan yang bertentangan dengan hukum.',duty:'Setiap orang menghormati kebebasan orang lain dan ketentuan hukum yang berlaku.'},
{article:'Pasal 28E Ayat (2)',title:'Kebebasan meyakini kepercayaan dan menyatakan sikap',text:'Setiap orang berhak atas kebebasan meyakini kepercayaan, menyatakan pikiran dan sikap, sesuai dengan hati nuraninya.',example:'Seseorang dapat menyatakan pandangan dan keyakinannya tanpa intimidasi.',duty:'Kebebasan dijalankan dengan menghormati hak, keselamatan, dan martabat orang lain.'},
{article:'Pasal 28E Ayat (3)',title:'Kebebasan berserikat, berkumpul, dan berpendapat',text:'Setiap orang berhak atas kebebasan berserikat, berkumpul, dan mengeluarkan pendapat.',example:'Siswa menyampaikan aspirasi melalui forum sekolah secara tertib dan bertanggung jawab.',duty:'Penyampaian pendapat harus menghormati hak orang lain dan peraturan yang berlaku.'},
{article:'Pasal 28F',title:'Hak berkomunikasi dan memperoleh informasi',text:'Setiap orang berhak untuk berkomunikasi dan memperoleh informasi untuk mengembangkan pribadi dan lingkungan sosialnya, serta berhak untuk mencari, memperoleh, memiliki, menyimpan, mengolah, dan menyampaikan informasi dengan menggunakan segala jenis saluran yang tersedia.',example:'Warga mencari informasi publik dari sumber tepercaya dan menyampaikan informasi secara bertanggung jawab.',duty:'Informasi tidak disebarkan dengan cara menyesatkan atau melanggar privasi pihak lain.'},
{article:'Pasal 28G Ayat (1)',title:'Perlindungan diri, keluarga, martabat, dan rasa aman',text:'Setiap orang berhak atas perlindungan diri pribadi, keluarga, kehormatan, martabat, dan harta benda yang di bawah kekuasaannya, serta berhak atas rasa aman dan perlindungan dari ancaman ketakutan untuk berbuat atau tidak berbuat sesuatu yang merupakan hak asasi.',example:'Korban ancaman berhak mencari pertolongan dan memperoleh perlindungan yang sesuai.',duty:'Setiap orang tidak mengancam, mengintimidasi, atau menyebarkan data pribadi orang lain.'},
{article:'Pasal 28G Ayat (2)',title:'Bebas dari penyiksaan dan perlakuan merendahkan martabat',text:'Setiap orang berhak untuk bebas dari penyiksaan atau perlakuan yang merendahkan derajat martabat manusia dan berhak memperoleh suaka politik dari negara lain.',example:'Orang yang berada dalam tahanan tetap harus diperlakukan manusiawi sesuai hukum.',duty:'Pihak berwenang dilarang melakukan penyiksaan dan wajib menghormati martabat manusia.'},
{article:'Pasal 28H Ayat (1)',title:'Hak atas kesejahteraan, tempat tinggal, lingkungan sehat, dan kesehatan',text:'Setiap orang berhak hidup sejahtera lahir dan batin, bertempat tinggal, dan mendapatkan lingkungan hidup yang baik dan sehat serta berhak memperoleh pelayanan kesehatan.',example:'Masyarakat membutuhkan udara bersih, lingkungan yang aman, tempat tinggal layak, dan layanan kesehatan.',duty:'Pemerintah dan masyarakat berperan menjaga lingkungan serta mendukung akses pelayanan kesehatan.'},
{article:'Pasal 28H Ayat (2)',title:'Hak atas kemudahan dan perlakuan khusus yang adil',text:'Setiap orang berhak mendapat kemudahan dan perlakuan khusus untuk memperoleh kesempatan dan manfaat yang sama guna mencapai persamaan dan keadilan.',example:'Aksesibilitas bagi penyandang disabilitas membantu menciptakan kesempatan yang setara.',duty:'Lembaga publik perlu mempertimbangkan kebutuhan berbeda agar akses dan kesempatan lebih setara.'},
{article:'Pasal 28H Ayat (3)',title:'Hak atas jaminan sosial',text:'Setiap orang berhak atas jaminan sosial yang memungkinkan pengembangan dirinya secara utuh sebagai manusia yang bermartabat.',example:'Program jaminan sosial membantu masyarakat menghadapi risiko sosial dan ekonomi.',duty:'Program jaminan sosial diselenggarakan sesuai ketentuan dan ditujukan kepada penerima yang berhak.'},
{article:'Pasal 28H Ayat (4)',title:'Hak milik pribadi',text:'Setiap orang berhak mempunyai hak milik pribadi dan hak milik tersebut tidak boleh diambil alih secara sewenang-wenang oleh siapa pun.',example:'Pengambilalihan hak milik harus memiliki dasar hukum dan tidak dilakukan sewenang-wenang.',duty:'Setiap orang menghormati hak milik orang lain; pembatasan harus sesuai ketentuan hukum.'},
{article:'Pasal 28I Ayat (1)',title:'Hak asasi yang tidak dapat dikurangi',text:'Hak untuk hidup, hak untuk tidak disiksa, hak untuk kemerdekaan pikiran dan hati nurani, hak beragama, hak untuk tidak diperbudak, hak untuk diakui sebagai pribadi di hadapan hukum, dan hak untuk tidak dituntut atas dasar hukum yang berlaku surut adalah hak asasi manusia yang tidak dapat dikurangi dalam keadaan apa pun.',example:'Keadaan darurat tidak menghapus perlindungan terhadap hak-hak yang disebut dalam ayat ini.',duty:'Negara menghormati, melindungi, dan memenuhi hak asasi manusia sesuai konstitusi.'},
{article:'Pasal 28I Ayat (2)',title:'Hak bebas dari diskriminasi',text:'Setiap orang berhak bebas dari perlakuan yang bersifat diskriminatif atas dasar apa pun dan berhak mendapatkan perlindungan terhadap perlakuan yang bersifat diskriminatif itu.',example:'Layanan pendidikan dan publik tidak boleh memberikan perlakuan diskriminatif tanpa dasar yang sah.',duty:'Setiap orang menghindari diskriminasi dan lembaga terkait menyediakan perlindungan yang setara.'},
{article:'Pasal 29 Ayat (2)',title:'Jaminan kemerdekaan beragama',text:'Negara menjamin kemerdekaan tiap-tiap penduduk untuk memeluk agamanya masing-masing dan untuk beribadat menurut agamanya dan kepercayaannya itu.',example:'Penduduk dapat menjalankan ibadah sesuai agama dan kepercayaannya.',duty:'Negara menjamin kebebasan beragama dan masyarakat saling menghormati.'},
{article:'Pasal 30 Ayat (1)',title:'Hak dan kewajiban dalam pertahanan dan keamanan',text:'Tiap-tiap warga negara berhak dan wajib ikut serta dalam usaha pertahanan dan keamanan negara.',example:'Warga berpartisipasi menjaga ketertiban dan keamanan melalui cara yang sah.',duty:'Partisipasi dilakukan sesuai peran warga dan ketentuan hukum.'},
{article:'Pasal 31 Ayat (1)',title:'Hak memperoleh pendidikan',text:'Setiap warga negara berhak mendapat pendidikan.',example:'Setiap warga negara berhak memperoleh akses pendidikan.',duty:'Negara menyelenggarakan sistem pendidikan; warga menghormati hak belajar orang lain.'}
]

